//! Dataset own-key snapshots retain exact native code units and actual attribute order.
use super::*;
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><p id=target></p><svg id=svg></svg></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://dataset-inspection.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}

#[test]
fn dataset_own_key_snapshot_exact_names_order_projection_empty_and_numeric(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset;for(var pair of [['data-first-name','one'],['data-x\ud800-b','raw'],['data-x\ufffd-b','scalar'],['data-0','zero'],['data-','empty']])n.setAttributeNS(null,pair[0],pair[1]);var expected=['firstName','x\ud800B','x\ufffdB','0',''];for(var keys of [Object.keys(d),Object.getOwnPropertyNames(d),Reflect.ownKeys(d)]){if(keys.length!==expected.length)throw 'exact native key count';for(var i=0;i<keys.length;i++)if(keys[i]!==expected[i])throw 'actual native attribute order and raw identity';}if(Object.keys(d)[1].charCodeAt(1)!==55296)throw 'not display projection';"#);}

#[test]
fn dataset_own_key_snapshot_values_entries_and_descriptor_map_use_native_presence(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset;n.setAttributeNS(null,'data-x\ud800','raw\udfff');n.setAttributeNS(null,'data-second-name','scalar');var values=Object.values(d),entries=Object.entries(d),descs=Object.getOwnPropertyDescriptors(d);if(values.length!==2||values[0]!=='raw\udfff'||values[1]!=='scalar'||entries.length!==2||entries[0][0]!=='x\ud800'||entries[0][1]!=='raw\udfff'||entries[1][0]!=='secondName'||descs['x\ud800'].value!=='raw\udfff'||!descs['x\ud800'].writable||!descs['x\ud800'].enumerable||!descs['x\ud800'].configurable)throw 'own consumers retain native raw data';"#);}

#[test]
fn dataset_own_key_snapshot_assign_copies_exact_keys_to_ordinary_and_native_receivers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset;n.setAttributeNS(null,'data-x\ud800-b','raw\udfff');n.setAttributeNS(null,'data-x\ufffd-b','scalar');var copy=Object.assign({},d),other=document.createElement('p');if(copy['x\ud800B']!=='raw\udfff'||copy['x\ufffdB']!=='scalar'||Object.keys(copy).length!==2)throw 'ordinary exact copy';if(Object.assign(other.dataset,d)!==other.dataset||other.getAttributeNS(null,'data-x\ud800-b')!=='raw\udfff'||other.dataset['x\ufffdB']!=='scalar')throw 'actual native copy target';"#);}

#[test]
fn dataset_own_key_snapshot_is_independent_and_live_reinsert_uses_attribute_order(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset;d.first='one';d['x\ud800']='two';var keys=Object.keys(d);delete d.first;d.third='three';d.first='last';var next=Object.keys(d);if(keys.length!==2||keys[0]!=='first'||keys[1]!=='x\ud800'||next.length!==3||next[0]!=='x\ud800'||next[1]!=='third'||next[2]!=='first')throw 'snapshot and native reinsert order';keys[0]='author';if(Object.keys(d)[0]!=='x\ud800'||d.first!=='last')throw 'snapshot is not native storage';"#);}

#[test]
fn dataset_own_key_snapshot_own_names_do_not_run_or_include_author_prototype_getters(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,hits=0;Object.defineProperty(DOMStringMap.prototype,'x\ud800',{get:function(){hits++;throw 'author getter';},enumerable:true,configurable:true});Object.defineProperty(DOMStringMap.prototype,'inherited',{get:function(){hits++;throw 'inherited getter';},enumerable:true,configurable:true});n.setAttributeNS(null,'data-x\ud800','native');if(Object.keys(d).length!==1||Object.keys(d)[0]!=='x\ud800'||Object.values(d)[0]!=='native'||Object.entries(d)[0][1]!=='native'||hits)throw 'native own source only';delete d['x\ud800'];if(Object.keys(d).length||Object.values(d).length||Reflect.ownKeys(d).length||hits)throw 'absent inherited properties excluded';"#);}

#[test]
fn dataset_own_key_snapshot_html_svg_null_namespace_and_ascii_case_membership(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var n of [document.getElementById('target'),document.getElementById('svg')]){var d=n.dataset;n.setAttributeNS(null,'data-x\ud800-name','native');n.setAttributeNS(null,'data-UP\ud800','excluded');if(n===document.getElementById('target'))n.setAttributeNS('urn:foreign','q:data-foreign\ud800','foreign');var keys=Object.keys(d);if(keys.length!==1||keys[0]!=='x\ud800Name'||Object.values(d)[0]!=='native')throw 'actual namespace and ASCII supported-name membership';}"#);}

#[test]
fn dataset_own_key_snapshot_resource_refusal_preserves_dom_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),data=n.dataset;n.setAttributeNS(null,'data-x\ud800','old\udfff');var watch=new MutationObserver(function(){});watch.observe(n,{attributes:true,attributeOldValue:true});"#);let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let limit=p.state.retained_limit;for mode in 0..4{p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.retained_limit=p.state.retained,2=>p.state.host_work=0,_=>p.state.execution_deadline=Some(Instant::now())};let error=p.runtime.execute("Object.keys(data);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(!error.is_empty());assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.state.retained_limit=limit;p.state.execution_deadline=None;run(&mut d,&mut f,&mut p,r#"if(watch.takeRecords().length||data['x\ud800']!=='old\udfff'||Object.keys(data)[0]!=='x\ud800')throw 'atomic snapshot refusal and recovery';"#);}}

#[test]
fn dataset_own_key_snapshot_assign_rechecks_deleted_native_names_without_adding_new_ones(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),data=n.dataset;data.first='one';data['later\ud800']='two';var target={},calls=0;Object.defineProperty(target,'first',{set:function(value){if(value!=='one')throw 'actual first value';calls++;delete data['later\ud800'];data['new\ud800']='added';}});Object.assign(target,data);if(calls!==1||Object.hasOwn(target,'later\ud800')||Object.hasOwn(target,'new\ud800')||data['new\ud800']!=='added'||Object.hasOwn(data,'later\ud800'))throw 'snapshot order and renewed native membership';"#);}

#[test]
fn dataset_own_key_snapshot_does_not_copy_attribute_values(){let(mut d,mut f,mut p)=fixture();let source=format!(r#"var n=document.getElementById('target'),data=n.dataset;n.setAttributeNS(null,'data-x\ud800','{}');"#,"x".repeat(16000));run(&mut d,&mut f,&mut p,&source);let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.begin_job();p.state.copy_work=128;p.runtime.execute(r#"if(Object.keys(data)[0]!=='x\ud800')throw 'actual raw key';"#,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap();assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}
